//
// a word-count application "plugin" for MapReduce.
//
// built by the Makefile into early_exit.so
//

#include <chrono>
#include <string>
#include <thread>
#include <vector>

#include "mr/mr.h"

//
// The map function is called once for each file of input.
// This map function just returns 1 for each file
//
static std::vector<mr::KeyValue> Map(const std::string& filename, const std::string& contents) {
    return {{filename, "1"}};
}

//
// The reduce function is called once for each key generated by the
// map tasks, with a list of all the values created for that key by
// any map task.
//
static std::string Reduce(const std::string& key, const std::vector<std::string>& values) {
    // some reduce tasks sleep for a long time; potentially seeing if
    // a worker will accidentally exit early
    if (key.find("sherlock") != std::string::npos || key.find("tom") != std::string::npos) {
        std::this_thread::sleep_for(std::chrono::seconds(3));
    }
    // return the number of occurrences of this file.
    return std::to_string(values.size());
}

extern "C" const mr::Plugin mr_plugin = {Map, Reduce};
